// Example: localStorage sync in a service
private syncWithLocalStorage() {
  // Read initial value
  const stored = localStorage.getItem('authState');
  if (stored) {
    this.authState$.next(stored === 'true');
  }

  // Subscribe to write changes
  this.authState$.subscribe(state => {
    localStorage.setItem('authState', String(state));
  });
}

